// Harbor nav beacon: 500 ms on / 500 ms off on D12.
// Quiet mode switch on D3 (pull-up). Status over UART.

const int BEACON_PIN = 12;
const int QUIET_PIN = 3;
const byte HALF_MS = 500;
const unsigned long STATUS_MS = 2000;
const unsigned long QUIET_DEBOUNCE_MS = 30;

bool lampOn = false;
unsigned long lastToggle = 0;
unsigned long lastStatus = 0;
unsigned long risingCount = 0;
bool quietHeld = false;
bool quietRaw = false;
unsigned long quietChangedAt = 0;

void setBeacon(bool on)
{
    lampOn = on;
    digitalWrite(BEACON_PIN, on ? HIGH : LOW);
}

void emitTick()
{
    Serial.println("tick");
    risingCount++;
}

void publishStatus()
{
    Serial.print("nav rises=");
    Serial.print(risingCount);
    Serial.print(" quiet=");
    Serial.println(quietHeld ? 1 : 0);
}

bool readQuiet()
{
    return digitalRead(QUIET_PIN) == LOW;
}

void setup()
{
    pinMode(BEACON_PIN, OUTPUT);
    pinMode(QUIET_PIN, INPUT_PULLUP);
    setBeacon(false);
    Serial.begin(9600);
    lastToggle = millis();
    lastStatus = millis();
    quietRaw = readQuiet();
    quietHeld = quietRaw;
    quietChangedAt = millis();
}

void loop()
{
    unsigned long now = millis();

    bool raw = readQuiet();
    if (raw != quietRaw)
    {
        quietRaw = raw;
        quietChangedAt = now;
    }
    if (quietHeld != quietRaw && (now - quietChangedAt) >= QUIET_DEBOUNCE_MS)
    {
        quietHeld = quietRaw;
        if (quietHeld)
        {
            setBeacon(false);
        }
        else
        {
            lastToggle = now;
        }
    }

    if (quietHeld)
    {
        setBeacon(false);
    }
    else if ((now - lastToggle) >= HALF_MS)
    {
        lastToggle += HALF_MS;
        bool nextOn = !lampOn;
        setBeacon(nextOn);
        if (nextOn)
        {
            emitTick();
        }
    }

    if (now - lastStatus >= STATUS_MS)
    {
        lastStatus = now;
        publishStatus();
    }
}
